def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # A horizontal 5-line spreads the color sequence beside it across its length.
    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c < w and grid[r][c] == 5:
                c += 1
            end = c - 1
            if end == start:
                continue

            for dr in (1, -1):
                rr = r + dr
                if not (0 <= rr < h) or grid[rr][start] in (0, 5):
                    continue
                while 0 <= rr < h and grid[rr][start] not in (0, 5):
                    color = grid[rr][start]
                    for cc in range(start, end + 1):
                        out[rr][cc] = color
                    rr += dr
                break

    # A vertical 5-line repeats the adjacent horizontal pattern along its length.
    for c in range(w):
        r = 0
        while r < h:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r < h and grid[r][c] == 5:
                r += 1
            end = r - 1
            if end == start:
                continue

            found = False
            for anchor, step in ((end, -1), (start, 1)):
                for dc in (1, -1):
                    side = c + dc
                    if not (0 <= side < w) or grid[anchor][side] in (0, 5):
                        continue

                    # The pattern block is attached to one endpoint of the line.
                    rows = []
                    rr = anchor
                    while 0 <= rr < h and grid[rr][side] not in (0, 5):
                        vals = []
                        cc = side
                        while 0 <= cc < w and grid[rr][cc] not in (0, 5):
                            vals.append(grid[rr][cc])
                            cc += dc
                        rows.append(vals)
                        rr += step

                    if not rows:
                        continue

                    k = len(rows)
                    for rr in range(start, end + 1):
                        offset = (anchor - rr) if step == -1 else (rr - anchor)
                        pattern = rows[offset % k]
                        for j, value in enumerate(pattern):
                            cc = side + dc * j
                            if 0 <= cc < w:
                                out[rr][cc] = value
                    found = True
                    break
                if found:
                    break

    return out
